import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;
import java.io.IOException;
import java.time.Duration;
import java.util.function.Supplier;

public class ResilientApiClient {

    private final CircuitBreaker circuitBreaker;
    private final Retry retry;

    public ResilientApiClient(CircuitBreaker circuitBreaker) {
        this.circuitBreaker = circuitBreaker;

        RetryConfig retryConfig = RetryConfig.<String>custom()
            .maxAttempts(3)
            .waitDuration(Duration.ofMillis(500))
            .retryOnException(ex -> ex instanceof IOException || ex instanceof java.net.http.HttpTimeoutException)
            .ignoreExceptions(IllegalArgumentException.class)
            .build();

        this.retry = Retry.of("thirdPartyApi", retryConfig);
    }

    public String callExternalService(Supplier<String> apiCall) {
        Supplier<String> decoratedCall = Retry.decorateSupplier(retry, apiCall);
        decoratedCall = CircuitBreaker.decorateSupplier(circuitBreaker, decoratedCall);

        try {
            return decoratedCall.get();
        } catch (Exception e) {
            // Fallback or graceful degradation path
            return "Fallback Response: Service temporarily unavailable";
        }
    }
}
